#!/usr/bin/env python3
# apply_trade_replay.py — fence TRADE_REPLAY_20260928
# (requires LOT_COMP_EQ_20260924 in Backtest.jsx — the trade table's Lots column)
#
# TRADE REPLAY: a ▶ button on every row of a backtest's trade log opens a
# full-screen replay of that trade group — underlying candles with the
# strategy's own indicators, the traded contract's candles (Heikin Ashi for
# HA_V1) or the basket MTM for multi-leg groups, entry/exit markers, SL/TP
# drawn on the pane they live on (spot for ORB/ORV/FVG/GC/CBO/STFC-spot),
# RSI where used; Prev/Next (← →) through the run's trade groups, Esc closes.
# Every indicator is recomputed by the strategy's OWN backtest code on the
# run's frozen config (tiers: exact / converged / copied / levels) — all 20
# strategy ids: SCALP_V1/V3/V5, HA_V1, BB_V1/V2, TMA_V1/V2, VET_V1, ORB_V1,
# ORV_V1, FVG_V1, STFC_V1, CBO_V1, GC_V1, VAP_V1, BRK_V1, TSG_V1, IC_V1/V2.
#
#   backend  app/backtest/replay/ (new: replay_core, overlays, replay_synth,
#            test_trade_replay — 159 checks: runs the REAL runners on a
#            synthetic corpus and checks the replay reconstructs their stops,
#            signal bars and baskets); backtest_routes.py (one read-only route
#            GET /api/backtest/runs/{run_id}/replay/{trade_id}, anchored insert)
#   frontend components/replay/TradeReplay.jsx (new); pages/Backtest.jsx
#            (5 anchored edits: import, state, ▶ column header + cell, modal)
#
# Read-only: no runner, engine, schema or config is touched.
# Deploy: ./desktop/build-scalp.sh both  (backend + frontend).
#
# Run ONLY this script:
#   cd /Users/anbu/dev/scalp-app && python3 apply_trade_replay.py [--allow-dirty] [--skip-tests]
from __future__ import annotations
import base64, os, py_compile, shutil, subprocess, sys, tempfile

FENCE = "TRADE_REPLAY_20260928"
ROOT = os.path.dirname(os.path.abspath(__file__))
MIRRORS = (("backend/app", "desktop/src-tauri/backend/app"), ("frontend/src", "desktop/src-tauri/frontend/src"))
PREREQ = {"frontend/src/pages/Backtest.jsx": "LOT_COMP_EQ_20260924",
          "backend/app/api/backtest_routes.py": "def run_csv(run_id: str):",
          "backend/app/backtest/fvg/backtest_fvg_runner.py": "FVG_V1_20260916",
          "backend/app/backtest/ha/backtest_ha_runner.py": "class _HAState",
          "backend/app/backtest/vet/backtest_vet_runner.py": "def _norm_cfg"}
EDITS = {"backend/app/api/backtest_routes.py": [["        headers={\"Content-Disposition\": f'attachment; filename=\"backtest_{run_id[:8]}.csv\"'},\n    )\n", "        headers={\"Content-Disposition\": f'attachment; filename=\"backtest_{run_id[:8]}.csv\"'},\n    )\n\n\n# \u2500\u2500 TRADE_REPLAY_20260928 \u2500\u2500 read-only replay payload for one trade group:\n# underlying + contract bars, the strategy's own indicators, entry/exit\n# markers, SL/TP on the pane they live on. See app/backtest/replay/.\n@router.get(\"/runs/{run_id}/replay/{trade_id}\")\ndef run_trade_replay(run_id: str, trade_id: int):\n    from app.backtest.replay.replay_core import build_replay\n    try:\n        out = build_replay(run_id, int(trade_id))\n    except Exception as e:\n        write_audit_log(f\"[BACKTEST][REPLAY] {run_id[:8]}/{trade_id} failed: {e!r}\")\n        raise HTTPException(500, f\"replay failed: {type(e).__name__}: {e}\")\n    if not out.get(\"ok\"):\n        raise HTTPException(404, out.get(\"error\") or \"not found\")\n    return out\n"]], "frontend/src/pages/Backtest.jsx": [["import Portfolio from \"./backtest/Portfolio\";   // \u2500\u2500 PORTFOLIO_VIEW \u2500\u2500\n", "import Portfolio from \"./backtest/Portfolio\";   // \u2500\u2500 PORTFOLIO_VIEW \u2500\u2500\nimport TradeReplay from \"../components/replay/TradeReplay\";   // \u2500\u2500 TRADE_REPLAY_20260928 \u2500\u2500\n"], ["  const [resultMeta, setResultMeta] = useState(null);   // {date_from, date_to} when known\n", "  const [resultMeta, setResultMeta] = useState(null);   // {date_from, date_to} when known\n  const [replayTradeId, setReplayTradeId] = useState(null);   // \u2500\u2500 TRADE_REPLAY_20260928 \u2500\u2500 open replay modal\n"], ["                      <tr>\n                        {(resultIsHedge\n                          ? [\"Signal\", \"Hedge\",", "                      <tr>\n                        {/* \u2500\u2500 TRADE_REPLAY_20260928 \u2500\u2500 replay column */}\n                        <th style={{ padding: \"9px 4px 9px 8px\", borderBottom: `2px solid ${colors.border.light}`, width: 34 }} title=\"Trade replay\" />\n                        {(resultIsHedge\n                          ? [\"Signal\", \"Hedge\","], ["                        <tr key={i} style={{ background: i % 2 ? colors.bg.secondary : colors.bg.primary, borderTop: `1px solid ${colors.border.dark}` }}>\n                          {resultIsHedge && (", "                        <tr key={i} style={{ background: i % 2 ? colors.bg.secondary : colors.bg.primary, borderTop: `1px solid ${colors.border.dark}` }}>\n                          {/* \u2500\u2500 TRADE_REPLAY_20260928 \u2500\u2500 open the replay for this row's trade group */}\n                          <td style={{ padding: \"4px 4px 4px 8px\" }}>\n                            {t.id != null && runId ? (\n                              <button type=\"button\" onClick={() => setReplayTradeId(t.id)} title=\"Replay this trade\"\n                                aria-label={`Replay trade ${t.id}`}\n                                style={{ width: 24, height: 22, borderRadius: 5, border: `1px solid ${colors.border.light}`,\n                                         background: \"transparent\", color: colors.primary, cursor: \"pointer\",\n                                         fontSize: 10, lineHeight: \"20px\", padding: 0 }}>\u25b6</button>\n                            ) : null}\n                          </td>\n                          {resultIsHedge && ("], ["          {/* EQUITY */}\n", "          {/* \u2500\u2500 TRADE_REPLAY_20260928 \u2500\u2500 full-screen replay (fixed overlay; survives tab switches) */}\n          {replayTradeId != null && runId && (\n            <TradeReplay runId={runId} tradeId={replayTradeId} onClose={() => setReplayTradeId(null)} />\n          )}\n\n          {/* EQUITY */}\n"]]}
NEW = {"backend/app/backtest/replay/__init__.py": "IyBiYWNrZW5kL2FwcC9iYWNrdGVzdC9yZXBsYXkg4oCUIOKUgOKUgCBUUkFERV9SRVBMQVlfMjAyNjA5Mjgg4pSA4pSAIHJlYWQtb25seSB0cmFkZSByZXBsYXkgcGF5bG9hZHMuCg==", "backend/app/backtest/replay/replay_core.py": "", "backend/app/backtest/replay/overlays.py": "", "backend/app/backtest/replay/replay_synth.py": "", "backend/app/backtest/replay/test_trade_replay.py": "", "frontend/src/components/replay/TradeReplay.jsx": ""}


def die(m):
    print("\nABORT:", m); sys.exit(1)


def mirror_of(rel):
    for src, dst in MIRRORS:
        if rel.startswith(src + "/"):
            root = os.path.join(ROOT, dst)
            return os.path.join(root, rel[len(src) + 1:]) if os.path.isdir(root) else None
    return None


print(f"── {FENCE}")
for rel, marker in PREREQ.items():
    p = os.path.join(ROOT, rel)
    if not os.path.exists(p):
        die(f"{rel} not found — run from the repo root")
    t = open(p, encoding="utf-8").read()
    if FENCE in t:
        die(f"{FENCE} already applied ({rel})")
    if marker not in t:
        die(f"prerequisite '{marker}' missing in {rel}")
for rel in NEW:
    if os.path.exists(os.path.join(ROOT, rel)):
        die(f"{rel} already exists — {FENCE} applied, or a hand-placed copy (remove it and re-run)")

staged = {}
for rel, ops in EDITS.items():
    t = open(os.path.join(ROOT, rel), encoding="utf-8").read()
    for old, new in ops:
        n = t.count(old)
        if n != 1:
            die(f"{rel}: anchor found {n}x (need 1): {old.strip().splitlines()[0][:80]!r}")
        t = t.replace(old, new)
    staged[rel] = t
for rel, b64 in NEW.items():
    staged[rel] = base64.b64decode(b64).decode("utf-8")

tmp = tempfile.mkdtemp(prefix="trade_replay_gate_")
for rel, txt in staged.items():
    if rel.endswith(".py"):
        p = os.path.join(tmp, os.path.basename(rel))
        open(p, "w", encoding="utf-8").write(txt)
        try:
            py_compile.compile(p, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"py_compile failed for {rel}: {e}")
shutil.rmtree(tmp, ignore_errors=True)
print("   py_compile ok")

st = subprocess.run(["git", "status", "--porcelain", "--"] + list(EDITS), cwd=ROOT, capture_output=True, text=True).stdout
dirty = [l for l in st.splitlines() if l.strip() and not l.startswith("??")]
if dirty and "--allow-dirty" not in sys.argv:
    die(f"uncommitted changes on targets ({dirty}); commit them or re-run with --allow-dirty")

written, created, mirrored = [], [], []
for rel, txt in staged.items():
    p = os.path.join(ROOT, rel)
    if rel in EDITS:
        shutil.copy2(p, p + f".bak-{FENCE}")
        written.append(rel)
    else:
        os.makedirs(os.path.dirname(p), exist_ok=True)
        created.append(rel)
    open(p, "w", encoding="utf-8").write(txt)
    m = mirror_of(rel)
    if m:
        os.makedirs(os.path.dirname(m), exist_ok=True)
        open(m, "w", encoding="utf-8").write(txt)
        mirrored.append(m)
open(os.path.join(ROOT, f".{FENCE}.done"), "w").write("applied\n")
print(f"   edited {len(written)}, created {len(created)} (backups .bak-{FENCE}; {len(mirrored)} desktop mirror writes)")


def rollback(reason):
    for rel in written:
        p = os.path.join(ROOT, rel)
        shutil.move(p + f".bak-{FENCE}", p)
        m = mirror_of(rel)
        if m and os.path.exists(m):
            shutil.copy2(p, m)
    for rel in created:
        for p in (os.path.join(ROOT, rel), mirror_of(rel)):
            if p and os.path.exists(p):
                os.remove(p)
    for d in ("backend/app/backtest/replay", "frontend/src/components/replay"):
        for p in (os.path.join(ROOT, d), mirror_of(d + "/x") and os.path.dirname(mirror_of(d + "/x"))):
            if p and os.path.isdir(p):
                shutil.rmtree(os.path.join(p, "__pycache__"), ignore_errors=True)
                if not os.listdir(p):
                    os.rmdir(p)
    os.remove(os.path.join(ROOT, f".{FENCE}.done"))
    die(reason)


if "--skip-tests" not in sys.argv:
    env = dict(os.environ, PYTHONPATH=os.path.join(ROOT, "backend"))
    s = "app/backtest/replay/test_trade_replay.py"
    print("   running the replay suite (real runners on a synthetic corpus, ~1 min)…")
    r = subprocess.run([sys.executable, s], cwd=os.path.join(ROOT, "backend"), env=env, capture_output=True, text=True, timeout=1500)
    tail = (r.stdout.strip().splitlines() or [""])[-1]
    print(f"   {'ok  ' if r.returncode == 0 else 'FAIL'} {s} — {tail[:90]}")
    if r.returncode != 0:
        print("\n".join(l for l in r.stdout.splitlines() if "FAIL" in l)[-3000:])
        print((r.stderr or "")[-2000:])
        rollback("replay suite failed; working copy restored")
esb = os.path.join(ROOT, "frontend", "node_modules", ".bin", "esbuild")
esb = os.environ.get("ESBUILD") or (esb if os.path.exists(esb) else shutil.which("esbuild"))
if esb:
    for rel in ("frontend/src/components/replay/TradeReplay.jsx", "frontend/src/pages/Backtest.jsx"):
        r = subprocess.run([esb, rel, "--loader:.jsx=jsx", "--jsx=automatic", "--log-level=error", "--outfile=/dev/null"],
                           cwd=ROOT, capture_output=True, text=True)
        if r.returncode != 0:
            rollback(f"esbuild parse failed for {rel}; restored:\n" + r.stderr[-1500:])
        print(f"   esbuild ok {rel}")
else:
    print("   (esbuild not found — JSX parse check skipped; the build will catch syntax)")
print(f"── {FENCE} applied. Next: ./desktop/build-scalp.sh both")
